import 'package:flutter/material.dart';\nimport 'package:provider/provider.dart';\nimport 'package:shimmer/shimmer.dart';\nimport '../constants/strings.dart';\nimport '../providers/ai_tools_provider.dart';\nimport '../widgets/ai_tool_card.dart';\nimport 'categories_screen.dart';\nimport 'search_screen.dart';\nimport 'favorites_screen.dart';\nimport 'profile_screen.dart';\n\nclass HomeScreen extends StatefulWidget {\n  const HomeScreen({Key? key}) : super(key: key);\n\n  @override\n  State<HomeScreen> createState() => _HomeScreenState();\n}\n\nclass _HomeScreenState extends State<HomeScreen> {\n  int _currentIndex = 0;\n\n  @override\n  Widget build(BuildContext context) {\n    return Scaffold(\n      body: IndexedStack(\n        index: _currentIndex,\n        children: [\n          _buildHomeContent(),\n          const CategoriesScreen(),\n          const SearchScreen(),\n          const FavoritesScreen(),\n          const ProfileScreen(),\n        ],\n      ),\n      bottomNavigationBar: _buildBottomNavBar(),\n    );\n  }\n\n  Widget _buildHomeContent() {\n    return Consumer<AIToolsProvider>(\n      builder: (context, toolsProvider, _) {\n        return RefreshIndicator(\n          onRefresh: () => toolsProvider.loadAllTools(),\n          child: CustomScrollView(\n            slivers: [\n              SliverAppBar(\n                expandedHeight: 120,\n                floating: true,\n                pinned: true,\n                backgroundColor: Theme.of(context).scaffoldBackgroundColor,\n                flexibleSpace: FlexibleSpaceBar(\n                  title: Text(AppStrings.appName),\n                  centerTitle: true,\n                ),\n                elevation: 0,\n              ),\n              SliverToBoxAdapter(\n                child: Padding(\n                  padding: const EdgeInsets.all(16),\n                  child: Column(\n                    crossAxisAlignment: CrossAxisAlignment.start,\n                    children: [\n                      Text(\n                        AppStrings.welcomeBack,\n                        style: Theme.of(context).textTheme.bodyLarge,\n                      ),\n                      const SizedBox(height: 8),\n                      Text(\n                        AppStrings.appTagline,\n                        style: Theme.of(context).textTheme.displaySmall,\n                      ),\n                    ],\n                  ),\n                ),\n              ),\n              SliverToBoxAdapter(\n                child: _buildFeaturedSection(context, toolsProvider),\n              ),\n              const SliverToBoxAdapter(child: SizedBox(height: 24)),\n              SliverToBoxAdapter(\n                child: Padding(\n                  padding: const EdgeInsets.symmetric(horizontal: 16),\n                  child: Row(\n                    mainAxisAlignment: MainAxisAlignment.spaceBetween,\n                    children: [\n                      Text(\n                        AppStrings.trending,\n                        style: Theme.of(context).textTheme.bodyLarge?.copyWith(\n                              fontWeight: FontWeight.bold,\n                            ),\n                      ),\n                      GestureDetector(\n                        onTap: () => setState(() => _currentIndex = 1),\n                        child: Text(\n                          AppStrings.exploreMore,\n                          style: Theme.of(context).textTheme.bodyMedium?.copyWith(\n                                color: Theme.of(context).primaryColor,\n                              ),\n                        ),\n                      ),\n                    ],\n                  ),\n                ),\n              ),\n              const SliverToBoxAdapter(child: SizedBox(height: 12)),\n              toolsProvider.isLoading\n                  ? SliverToBoxAdapter(child: _buildLoadingGrid())\n                  : SliverPadding(\n                      padding: const EdgeInsets.symmetric(horizontal: 16),\n                      sliver: SliverGrid(\n                        gridDelegate: const SliverGridDelegateWithFixedCrossAxisCount(\n                          crossAxisCount: 2,\n                          childAspectRatio: 0.85,\n                          mainAxisSpacing: 16,\n                          crossAxisSpacing: 16,\n                        ),\n                        delegate: SliverChildBuilderDelegate(\n                          (context, index) {\n                            if (index < toolsProvider.trendingTools.length) {\n                              return AIToolCard(\n                                tool: toolsProvider.trendingTools[index],\n                              );\n                            }\n                            return SizedBox.shrink();\n                          },\n                          childCount: toolsProvider.trendingTools.length,\n                        ),\n                      ),\n                    ),\n              const SliverToBoxAdapter(child: SizedBox(height: 32)),\n            ],\n          ),\n        );\n      },\n    );\n  }\n\n  Widget _buildFeaturedSection(BuildContext context, AIToolsProvider provider) {\n    if (provider.isLoading || provider.allTools.isEmpty) {\n      return _buildLoadingCard();\n    }\n\n    final tool = provider.allTools.first;\n\n    return Padding(\n      padding: const EdgeInsets.symmetric(horizontal: 16),\n      child: Container(\n        decoration: BoxDecoration(\n          borderRadius: BorderRadius.circular(16),\n          gradient: LinearGradient(\n            begin: Alignment.topLeft,\n            end: Alignment.bottomRight,\n            colors: [\n              Theme.of(context).primaryColor,\n              Theme.of(context).primaryColor.withOpacity(0.7),\n            ],\n          ),\n        ),\n        child: Padding(\n          padding: const EdgeInsets.all(20),\n          child: Column(\n            crossAxisAlignment: CrossAxisAlignment.start,\n            children: [\n              Row(\n                children: [\n                  Container(\n                    width: 60,\n                    height: 60,\n                    decoration: BoxDecoration(\n                      borderRadius: BorderRadius.circular(12),\n                      color: Colors.white.withOpacity(0.2),\n                    ),\n                    child: Center(\n                      child: Image.network(\n                        tool.iconUrl,\n                        width: 40,\n                        height: 40,\n                        errorBuilder: (_, __, ___) => const Icon(\n                          Icons.api,\n                          size: 30,\n                          color: Colors.white,\n                        ),\n                      ),\n                    ),\n                  ),\n                  const SizedBox(width: 16),\n                  Expanded(\n                    child: Column(\n                      crossAxisAlignment: CrossAxisAlignment.start,\n                      children: [\n                        Text(\n                          AppStrings.featured,\n                          style: TextStyle(\n                            fontSize: 12,\n                            fontWeight: FontWeight.w600,\n                            color: Colors.white.withOpacity(0.8),\n                            letterSpacing: 1,\n                          ),\n                        ),\n                        const SizedBox(height: 4),\n                        Text(\n                          tool.name,\n                          style: const TextStyle(\n                            fontSize: 20,\n                            fontWeight: FontWeight.bold,\n                            color: Colors.white,\n                          ),\n                        ),\n                      ],\n                    ),\n                  ),\n                ],\n              ),\n              const SizedBox(height: 12),\n              Text(\n                tool.description,\n                maxLines: 2,\n                overflow: TextOverflow.ellipsis,\n                style: TextStyle(\n                  color: Colors.white.withOpacity(0.9),\n                  fontSize: 14,\n                  height: 1.4,\n                ),\n              ),\n              const SizedBox(height: 16),\n              ElevatedButton(\n                onPressed: () {},\n                style: ElevatedButton.styleFrom(\n                  backgroundColor: Colors.white,\n                  foregroundColor: Theme.of(context).primaryColor,\n                ),\n                child: Text(AppStrings.openInApp),\n              ),\n            ],\n          ),\n        ),\n      ),\n    );\n  }\n\n  Widget _buildLoadingGrid() {\n    return Padding(\n      padding: const EdgeInsets.symmetric(horizontal: 16),\n      child: GridView.builder(\n        gridDelegate: const SliverGridDelegateWithFixedCrossAxisCount(\n          crossAxisCount: 2,\n          childAspectRatio: 0.85,\n          mainAxisSpacing: 16,\n          crossAxisSpacing: 16,\n        ),\n        itemCount: 4,\n        itemBuilder: (context, index) => _buildLoadingCard(),\n        shrinkWrap: true,\n        physics: const NeverScrollableScrollPhysics(),\n      ),\n    );\n  }\n\n  Widget _buildLoadingCard() {\n    return Shimmer.fromColors(\n      baseColor: Theme.of(context).cardColor,\n      highlightColor: Theme.of(context).cardColor.withOpacity(0.5),\n      child: Container(\n        decoration: BoxDecoration(\n          borderRadius: BorderRadius.circular(12),\n          color: Colors.white,\n        ),\n      ),\n    );\n  }\n\n  Widget _buildBottomNavBar() {\n    return BottomNavigationBar(\n      currentIndex: _currentIndex,\n      onTap: (index) => setState(() => _currentIndex = index),\n      type: BottomNavigationBarType.fixed,\n      items: [\n        BottomNavigationBarItem(\n          icon: const Icon(Icons.home),\n          label: AppStrings.home,\n        ),\n        BottomNavigationBarItem(\n          icon: const Icon(Icons.category),\n          label: AppStrings.categories,\n        ),\n        BottomNavigationBarItem(\n          icon: const Icon(Icons.search),\n          label: AppStrings.search,\n        ),\n        BottomNavigationBarItem(\n          icon: const Icon(Icons.favorite),\n          label: AppStrings.favorites,\n        ),\n        BottomNavigationBarItem(\n          icon: const Icon(Icons.person),\n          label: AppStrings.profile_text,\n        ),\n      ],\n    );\n  }\n}\n